-- ============================================
-- LUMA — Thème 3 : MOYEN 2/3 x4 — Gérer une question piège
-- ============================================


update scenarios set content = '{"characters": {"recruiter": "le recruteur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "recruiter", "text": "So, why did you leave your last position?", "text_fr": "Alors, pourquoi avez-vous quitté votre dernier poste ?", "choices": [{"text": "I felt I had learned everything I could there and wanted new challenges.", "text_fr": "J''ai senti que j''avais tout appris de ce que je pouvais et voulais de nouveaux défis.", "next": "n2"}, {"text": "Honestly, there were some communication issues with my manager.", "text_fr": "Honnêtement, il y avait des problèmes de communication avec mon manager.", "next": "n2b"}]}, "n2": {"speaker": "recruiter", "text": "That''s understandable. What kind of challenges are you looking for now?", "text_fr": "C''est compréhensible. Quel genre de défis recherchez-vous maintenant ?", "choices": [{"text": "Something with more ownership over projects from start to finish.", "text_fr": "Quelque chose avec plus de responsabilité sur les projets du début à la fin.", "next": "n3"}, {"text": "I''d love to work in a more collaborative, cross-functional environment.", "text_fr": "J''aimerais travailler dans un environnement plus collaboratif, transversal.", "next": "n3"}]}, "n2b": {"speaker": "recruiter", "text": "I appreciate the honesty. Can you tell me more about that, without going into too much detail?", "text_fr": "J''apprécie l''honnêteté. Vous pouvez m''en dire plus, sans trop entrer dans les détails ?", "choices": [{"text": "We had different working styles, but I learned a lot from the experience.", "text_fr": "On avait des styles de travail différents, mais j''ai beaucoup appris de cette expérience.", "next": "n3"}, {"text": "It taught me a lot about the kind of management style that works for me.", "text_fr": "Ça m''a beaucoup appris sur le style de management qui me convient.", "next": "n3"}]}, "n3": {"speaker": "recruiter", "text": "That''s a mature way to frame it. Now — what''s your greatest weakness?", "text_fr": "C''est une façon mature de le formuler. Maintenant — quel est votre plus grand point faible ?", "choices": [{"text": "I sometimes take on too much, trying to help wherever I can.", "text_fr": "Je prends parfois trop de choses, en essayant d''aider partout où je peux.", "next": "n4"}, {"text": "I can be overly critical of my own work before sharing it.", "text_fr": "Je peux être trop critique envers mon propre travail avant de le partager.", "next": "n4"}]}, "n4": {"speaker": "recruiter", "text": "How have you worked on that?", "text_fr": "Comment avez-vous travaillé là-dessus ?", "choices": [{"text": "I''ve started setting clearer boundaries and prioritizing tasks better.", "text_fr": "J''ai commencé à établir des limites plus claires et à mieux prioriser les tâches.", "next": "n5"}, {"text": "I set myself deadlines to share work earlier, even if imperfect.", "text_fr": "Je me fixe des délais pour partager le travail plus tôt, même imparfait.", "next": "n5"}]}, "n5": {"speaker": "recruiter", "text": "Good, that shows self-awareness. Here''s a tough one — where do you see yourself in five years?", "text_fr": "Bien, ça montre de la conscience de soi. En voici une difficile — où vous voyez-vous dans cinq ans ?", "choices": [{"text": "Ideally in a leadership role, having grown within this company.", "text_fr": "Idéalement dans un rôle de leadership, ayant évolué au sein de cette entreprise.", "next": "n6"}, {"text": "Honestly, I''m focused on growing my skills — the exact title matters less to me.", "text_fr": "Honnêtement, je me concentre sur le développement de mes compétences — le titre exact m''importe moins.", "next": "n6b"}]}, "n6": {"speaker": "recruiter", "text": "Ambitious, I like that. What kind of leadership style appeals to you?", "text_fr": "Ambitieux, j''aime ça. Quel style de leadership vous attire ?", "choices": [{"text": "Collaborative — I believe in empowering the team, not just directing it.", "text_fr": "Collaboratif — je crois en la responsabilisation de l''équipe, pas juste la diriger.", "next": "n7"}]}, "n6b": {"speaker": "recruiter", "text": "That''s a refreshingly honest answer. What matters most to you in your growth?", "text_fr": "C''est une réponse rafraîchissante d''honnêteté. Qu''est-ce qui compte le plus pour vous dans votre évolution ?", "choices": [{"text": "Learning from people smarter than me and taking on real challenges.", "text_fr": "Apprendre de personnes plus intelligentes que moi et relever de vrais défis.", "next": "n7"}]}, "n7": {"speaker": "recruiter", "text": "I appreciate your thoughtfulness on these questions. One last tricky one — tell me about a failure.", "text_fr": "J''apprécie votre réflexion sur ces questions. Une dernière délicate — parlez-moi d''un échec.", "choices": [{"text": "I once missed a deadline because I underestimated the workload.", "text_fr": "J''ai une fois manqué un délai parce que j''avais sous-estimé la charge de travail.", "next": "n8"}, {"text": "I launched a project that didn''t get the results we hoped for.", "text_fr": "J''ai lancé un projet qui n''a pas obtenu les résultats espérés.", "next": "n8"}]}, "n8": {"speaker": "recruiter", "text": "What did you learn from that?", "text_fr": "Qu''avez-vous appris de ça ?", "choices": [{"text": "To build in more buffer time and communicate risks earlier.", "text_fr": "À prévoir plus de marge et à communiquer les risques plus tôt.", "next": "n9"}, {"text": "To gather more data before launching, and to iterate faster.", "text_fr": "À rassembler plus de données avant de lancer, et à itérer plus vite.", "next": "n9"}]}, "n9": {"speaker": "recruiter", "text": "That''s a great growth mindset. I think we''ve covered a lot of ground today.", "text_fr": "C''est un excellent état d''esprit de progression. Je pense qu''on a couvert beaucoup de terrain aujourd''hui.", "choices": [{"text": "Thank you, I really appreciated the thoughtful questions.", "text_fr": "Merci, j''ai vraiment apprécié les questions réfléchies.", "next": "end_handled"}]}, "end_handled": {"speaker": "recruiter", "text": "You handled those tricky questions with real honesty and self-awareness.", "text_fr": "Vous avez géré ces questions délicates avec une réelle honnêteté et conscience de soi.", "end": true, "ending_label": "Questions pièges gérées avec brio 🎯✅"}}}'::jsonb, is_playable = true
where title = 'Gérer une question piège'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));
